1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidOwnerEmailException;
9	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
10	import org.springframework.web.bind.annotation.RequestBody;
11	
12	/**
13	 * Runs first in the create-owner pipeline. Rejects a request that is missing or blank in any of
14	 * firstName, lastName, address, city or telephone by throwing {@link MissingOwnerFieldsException}
15	 * with the names of every offending field. Otherwise it publishes the body for later steps.
16	 */
17	public class ValidateOwnerFields {
18	
19	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
20	            throws MissingOwnerFieldsException, InvalidOwnerEmailException {
21	        List<String> missing = new ArrayList<>();
22	        if (isBlank(request.getFirstName())) {
23	            missing.add("firstName");
24	        }
25	        if (isBlank(request.getLastName())) {
26	            missing.add("lastName");
27	        }
28	        if (isBlank(request.getAddress())) {
29	            missing.add("address");
30	        }
31	        if (isBlank(request.getCity())) {
32	            missing.add("city");
33	        }
34	        if (isBlank(request.getTelephone())) {
35	            missing.add("telephone");
36	        }
37	        if (!missing.isEmpty()) {
38	            throw new MissingOwnerFieldsException(missing);
39	        }
40	        // Normalize telephone to its digits, then require exactly 10 of them.
41	        String telephone = request.getTelephone().replaceAll("\\D", "");
42	        if (telephone.length() != 10) {
43	            throw new MissingOwnerFieldsException(List.of("telephone"));
44	        }
45	        request.setTelephone(telephone);
46	        // An owner may include an email; when present it must be valid and is stored lower-cased.
47	        OwnerEmail.normalize(request);
48	        validated.set(request);
49	    }
50	
51	    private static boolean isBlank(String value) {
52	        return value == null || value.isBlank();
53	    }
54	}
