3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
8	
9	/**
10	 * Rejects a create-owner request whose normalized telephone is already used by any other owner.
11	 * Runs after {@link ValidateOwnerFields} has normalized the body's telephone to its digits, and
12	 * compares it against every existing owner's telephone (normalized the same way). Throws
13	 * {@link DuplicateTelephoneException} (handled as 409) on a collision.
14	 */
15	public class CheckOwnerTelephoneUnique {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateTelephoneException {
19	        String telephone = normalize(request.getTelephone());
20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (telephone.equals(normalize(existing.getTelephone()))) {
22	                throw new DuplicateTelephoneException(request.getTelephone());
23	            }
24	        }
25	    }
26	
27	    private static String normalize(String value) {
28	        return value == null ? "" : value.replaceAll("\\D", "");
29	    }
30	}
